DOCUMENTS = [
('F01','Product Requirements','F01_Product_Requirements.html','内容定稿 · 待签收'),
('F02','System Architecture','F02_System_Architecture.html','设计候选 · 待批准'),
('F03','Domain & Data Model','F03_Domain_and_Data_Model.html','设计候选 · 待评审'),
('F04','Contract Governance','F04_API_Contract_Governance.html','已编制'),
('F05','Security & Multitenancy','F05_Security_and_Multitenancy.html','规划中'),
('F06','Dual Portal Experience',None,'规划中'),
('F07','Engineering & Quality',None,'规划中'),
('F08','Delivery & Acceptance',None,'规划中')]

def render():
    md_text = SOURCE.read_text(encoding='utf-8')
    md = MarkdownIt('default', {'html':True, 'linkify': False, 'typographer':False})
    md.enable('table')
    rendered = md.render(md_text)
    for k,v in [('FABRIC_OVERVIEW_DIAGRAM',FIG_OVERVIEW),('FABRIC_RELATIONSHIP_DIAGRAM',FIG_RELATIONSHIP),('FABRIC_CAPABILITY_DIAGRAM',FIG_CAPABILITY),('FABRIC_JOURNEY_DIAGRAM',FIG_JOURNEY),('FABRIC_ROADMAP_DIAGRAM',FIG_ROADMAP),('FABRIC_LIFECYCLE_DIAGRAM',FIG_LIFECYCLE),('FABRIC_PORTALS_DIAGRAM',FIG_PORTALS),('FABRIC_TRACE_DIAGRAM',FIG_TRACE)]:
        rendered = rendered.replace(f'<!-- {k} -->',v)
    soup = BeautifulSoup(rendered,'html.parser')
    # One visible and semantic H1 belongs to the document's cover, not the Markdown duplicate.
    source_h1=soup.find('h1')
    if source_h1: source_h1.decompose()
    for table in list(soup.find_all('table')):
        wrapper=soup.new_tag('div', attrs={'class':'table-scroll', 'role':'region', 'aria-label':'可横向滚动的需求及规范表格', 'tabindex':'0'})
        table.wrap(wrapper)
    headings=[]
    for heading in soup.select('h2,h3'):
        text=heading.get_text(' ',strip=True)
        sec = re.match(r'^(\d+(?:\.\d+)*)(?:\.)?(?=\s|$)',text)
        anchor = ('section-' + (sec.group(1).replace('.','-') if sec else str(len(headings)+1)))
        heading['id']=anchor
        headings.append((anchor,text,heading.name))
    nav = '\n'.join(f'<a href="#{html.escape(anchor)}" class="{"sub" if typ=="h3" else ""}" style="{"padding-left:24px" if typ=="h3" else ""}">{html.escape(title)}</a>' for anchor,title,typ in headings)
    doc_menu=''.join((f'<a href="{name}" class="{"active" if code=="F01" else ""}">{code} · {label}</a>' if name else f'<div class="pending">{code} · {label} <span class="mini">待编写</span></div>') for code,label,name,_ in DOCUMENTS)
    JS = """(()=>{const m=document.getElementById('menu'),q=document.getElementById('navsearch'),toc=document.getElementById('toc'),backdrop=document.getElementById('sideBackdrop');let lastFocus=null;function setOpen(v){document.body.classList.toggle('navopen',v);m.setAttribute('aria-expanded',String(v));backdrop.setAttribute('aria-hidden',String(!v));if(v){lastFocus=document.activeElement;q.focus()}else if(lastFocus){lastFocus.focus();lastFocus=null}}m.addEventListener('click',()=>setOpen(!document.body.classList.contains('navopen')));backdrop.addEventListener('click',()=>setOpen(false));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.body.classList.contains('navopen'))setOpen(false)});toc.addEventListener('click',e=>{if(e.target.closest('a')&&document.body.classList.contains('navopen'))setOpen(false)});q.addEventListener('input',()=>{const search=q.value.toLocaleLowerCase();toc.querySelectorAll('a').forEach(a=>{a.style.display=a.textContent.toLocaleLowerCase().includes(search)?'':'none'})});})();"""
    body=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>F01 · IDP API Fabric 产品需求与能力蓝图</title><meta name="description" content="IDP API Fabric V1.0 F01 产品需求与能力蓝图，包含双门户、API契约治理、多产品自治、功能清单及验收矩阵。">{STYLE}{EXTRA_STYLE}</head><body><a class="skip-link" href="#main-content">跳到文档正文</a><button id="sideBackdrop" class="side-backdrop" aria-label="关闭章节目录" aria-hidden="true" tabindex="-1"></button><div class="layout">
<aside class="side" id="sidebar"><a href="../index.html" style="text-decoration:none"><div class="logo">IDP API Fabric<small>ENGINEERING BASELINE</small></div></a><div class="side-kicker">文档体系</div><div class="navlist">{doc_menu}</div><hr><div class="side-kicker">F01 · 目录</div><input id="navsearch" type="search" placeholder="筛选本文章节…" aria-label="筛选目录章节"><nav class="navlist" id="toc">{nav}</nav><div class="side-foot">V1.0 · 内容定稿 / 待签收<br>Markdown 为需求正文权威源；图示模板由构建脚本维护。</div></aside>
<div class="main"><header class="topbar"><div><button class="menu" id="menu" aria-label="展开目录" aria-controls="sidebar" aria-expanded="false">☰ 目录</button><span class="crumb"><strong>IDP API Fabric</strong>　/　设计基线　/　F01</span></div><div class="top-actions"><a class="desktop-only" href="../index.html">总目录</a><a href="F01_Product_Requirements.md">Markdown 源文件</a><button onclick="window.print()">打印 / PDF</button></div></header>
<main id="main-content" class="sheet" tabindex="-1"><div class="hero"><div class="eyebrow">F01 · Product Requirements & Capability Blueprint</div><h1>IDP API Fabric<br>产品需求与能力蓝图</h1><p>企业级 API 契约治理与开发者体验平台 · 多产品联邦治理 · 双门户产品需求 · Go + DDD 工程输入</p><div class="hero-meta"><span>V1.0 · 内容定稿 / 待签收</span><span>2026.11.09</span><span>内部工程文档</span><span>待具名签收 · 未验收</span></div></div>
<div class="metrics"><div class="metric"><b>8</b><span>核心设计文档（F01–F08）</span></div><div class="metric"><b>2</b><span>独立体验门户</span></div><div class="metric"><b>71</b><span>功能需求（FR-001–071）</span></div><div class="metric"><b>12</b><span>端到端验收意图</span></div></div>
<article class="doc">{str(soup)}</article><div class="footer">IDP API Fabric · F01 · Generated from Markdown source · Content finalized, approval pending</div></main></div></div><a href="#" class="back-to-top">↑ 返回顶部</a>
<script>{JS}</script></body></html>'''
    TARGET.write_text(body,encoding='utf-8')
    return len(headings)

if __name__ == '__main__':
    count = render()
    print(f'Built {TARGET.relative_to(ROOT)} ({count} headings)')
